import {lessons} from './content.js';
import {market,saturday,trade,utility,extraJoy,thrift,game} from './models.mjs';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const money=(n)=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:Number.isInteger(n)?0:2}).format(n);
let completed=new Set();try{completed=new Set(JSON.parse(localStorage.getItem('economics-easy-progress')||'[]').filter(id=>lessons.some(l=>l.id===id)));}catch{}
let current=lessons[0],quizAnswers={},state={demand:0,supply:0,hours:3,rate:15,specialise:false,tradeSalads:1,slices:3,saving:20,a:'normal',b:'normal'};
const minis=[
 '<path d="M12 56L110 12M12 12L110 56"/><circle cx="61" cy="34" r="6" fill="currentColor"/>',
 '<path d="M15 16H100V55H15Z M15 35H100 M43 16V55 M72 16V55"/><path d="M86 7V23M22 7V23"/>',
 '<path d="M12 25H99M88 14L99 25 88 36M110 49H23M34 38L23 49 34 60"/>',
 '<path d="M13 58V12M13 58H112M23 24L41 33 59 40 77 45 95 49 112 51"/><circle cx="23" cy="24" r="3" fill="currentColor"/><circle cx="59" cy="40" r="3" fill="currentColor"/><circle cx="95" cy="49" r="3" fill="currentColor"/>',
 '<path d="M31 30C35 11 58 7 76 14C88 18 96 26 99 36M89 31L99 36 101 25M97 46C93 65 70 69 52 62C40 58 32 50 29 40M39 45L29 40 27 51"/>',
 '<path d="M24 12H100V62H24ZM62 12V62M24 37H100"/><path d="M34 23H48M75 50H90"/><circle cx="83" cy="24" r="5"/><circle cx="43" cy="50" r="5"/>'
];
function mini(i){return `<svg viewBox="0 0 128 76" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${minis[i]}</svg>`}
function renderCatalog(){ $('#lesson-grid').innerHTML=lessons.map((l,i)=>`<a class="lesson-card" href="#lesson/${l.id}"><div class="card-top"><span>0${i+1}</span><b>${completed.has(l.id)?'✓ UNDERSTOOD':''}</b></div><div class="card-visual">${mini(i)}</div><span class="eyebrow">${l.category}</span><h3>${l.title}</h3><p>${l.question}</p><div class="card-bottom"><span>Explore the idea</span><span aria-hidden="true">↗</span></div></a>`).join('');}
function renderNav(){ $('#lesson-nav').innerHTML=lessons.map((l,i)=>`<a class="lesson-link ${l.id===current.id?'active':''}" ${l.id===current.id?'aria-current="page"':''} href="#lesson/${l.id}"><span>0${i+1}</span><span>${l.title}</span><span>${completed.has(l.id)?'✓':'↗'}</span></a>`).join('');$('#progress-label').textContent=`${completed.size} of 6 understood`;$('#progress-fill').style.width=`${completed.size/6*100}%`;}
function renderLesson(){const l=current,i=lessons.indexOf(l);renderNav();$('#lesson-content').innerHTML=`<article aria-labelledby="lesson-title"><header class="lesson-heading"><span class="eyebrow">IDEA 0${i+1} / ${l.title.toUpperCase()}</span><h2 id="lesson-title">${l.question}</h2><p>${l.intro}</p></header><div class="lesson-body"><div class="reading-grid"><div><h3>IN PLAIN ENGLISH</h3><p class="simple-text">${l.simple}</p></div><div><h3>PICTURE THIS</h3><p class="story-text">${l.story}</p></div></div><div class="takeaway"><b>THE THING TO REMEMBER</b>${l.takeaway}</div><section class="experiment" aria-labelledby="experiment-title"><div class="experiment-head"><span class="eyebrow">TRY IT YOURSELF / ILLUSTRATIVE MODEL</span><h3 id="experiment-title">${l.experiment}</h3><p>${l.instructions}</p></div><div id="experiment" class="experiment-content"></div></section><details class="nuance"><summary>Where the simple story gets complicated</summary><p>${l.caveat}</p><a class="source-link" href="${l.url}" target="_blank" rel="noopener">${l.source} ↗</a></details><section class="quiz" aria-label="Check your understanding"><span class="eyebrow">ONE QUICK CHECK</span><h3>${l.quiz}</h3><div class="answers" id="answers"></div><div id="feedback" role="status"></div></section><div class="lesson-footer"><button class="complete ${completed.has(l.id)?'done':''}" id="complete" aria-pressed="${completed.has(l.id)}">${completed.has(l.id)?'✓ Understood':'Mark as understood ✓'}</button><a class="next-lesson" href="${i<5?'#lesson/'+lessons[i+1].id:'#lessons'}">${i<5?'Next: '+lessons[i+1].title:'Back to the six ideas'} <span aria-hidden="true">→</span></a></div></div></article>`;renderExperiment();renderQuiz();$('#complete').onclick=()=>{completed.has(l.id)?completed.delete(l.id):completed.add(l.id);try{localStorage.setItem('economics-easy-progress',JSON.stringify([...completed]));}catch{}renderCatalog();renderNav();const b=$('#complete');b.classList.toggle('done',completed.has(l.id));b.setAttribute('aria-pressed',completed.has(l.id));b.textContent=completed.has(l.id)?'✓ Understood':'Mark as understood ✓';};}
function renderQuiz(){const l=current,a=quizAnswers[l.id];$('#answers').innerHTML=l.answers.map((answer,i)=>`<button class="answer ${a!==undefined&&i===l.correct?'correct':a===i?'wrong':''}" data-answer="${i}" aria-pressed="${a===i}"><span>${String.fromCharCode(65+i)}</span>${answer}${a!==undefined&&i===l.correct?' ✓':''}</button>`).join('');$$('[data-answer]').forEach(b=>b.onclick=()=>{quizAnswers[l.id]=Number(b.dataset.answer);renderQuiz();});$('#feedback').innerHTML=a===undefined?'':`<div class="feedback"><b>${a===l.correct?'Exactly.':'Good question to pause on. Here’s the idea:'}</b>${l.feedback}</div>`;}
function control(key,label,value,min,max,step=1,format=v=>v,ends=['Less','More']){return `<div class="control"><label for="${key}">${label}<output for="${key}" id="out-${key}">${format(value)}</output></label><input id="${key}" data-control="${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><div class="range-ends"><span>${ends[0]}</span><span>${ends[1]}</span></div></div>`}
function metric(value,label){return `<div><b>${value}</b><span>${label}</span></div>`}
function svgChart(content,title){return `<svg viewBox="0 0 400 245" role="img" aria-label="${title}">${content}</svg>`;}
function axes(x='Quantity',y='Price'){return `<path d="M45 18V211H380" fill="none" stroke="#aeb4a3"/><path d="M45 68H380M45 116H380M45 164H380" class="grid-line"/><text x="45" y="238">${x} →</text><text x="10" y="100" transform="rotate(-90 10 100)">${y} →</text>`;}
function marketPlot(){const {price,quantity}=market(state.demand,state.supply);const x=q=>45+q/125*330,y=p=>211-p/8*190;const pointsD=[0,8].map(p=>`${x(100+state.demand-10*p)},${y(p)}`).join(' '),pointsS=[0,8].map(p=>`${x(20+state.supply+10*p)},${y(p)}`).join(' ');return svgChart(`<defs><clipPath id="plotClip"><rect x="45" y="18" width="335" height="193"/></clipPath></defs>${axes('Cups per hour','€ per cup')}<g clip-path="url(#plotClip)"><polyline points="${pointsD}" fill="none" stroke="#8b9f57" stroke-width="3"/><polyline points="${pointsS}" fill="none" stroke="#20281b" stroke-width="3"/></g><path d="M${x(quantity)} ${y(price)}V211M45 ${y(price)}H${x(quantity)}" fill="none" stroke="#8c957c" stroke-dasharray="4 5"/><circle cx="${x(quantity)}" cy="${y(price)}" r="7" fill="#10130f" stroke="#d6ff5f" stroke-width="3"/><text x="${x(quantity)+12}" y="${y(price)-12}" style="fill:#10130f;font-size:13px">${money(price)} · ${quantity} cups</text><text x="43" y="225">0</text><text x="359" y="225">125</text>`,`Supply and demand meet at ${money(price)} and ${quantity} cups per hour.`);}
function utilityPlot(){const {slices}=state;const total=extraJoy.map((_,i)=>utility(i+1).total);const x=i=>65+i*56,y=n=>204-n/32*170;return svgChart(`${axes('Pizza slices','Illustrative joy points')}<polyline points="${total.map((t,i)=>x(i)+','+y(t)).join(' ')}" fill="none" stroke="#161d15" stroke-width="2"/>${extraJoy.map((v,i)=>`<rect x="${x(i)-12}" y="${y(v)}" width="24" height="${204-y(v)}" fill="${i<slices?'#9cae76':'#dfe2d4'}"/><circle cx="${x(i)}" cy="${y(total[i])}" r="${i+1===slices?6:3}" fill="${i+1===slices?'#10130f':'#8a947c'}"/><text x="${x(i)-3}" y="225">${i+1}</text>`).join('')}`,`Total enjoyment rises with each slice, while extra enjoyment falls. ${slices} slices give ${utility(slices).total} total points and ${utility(slices).marginal} extra points from the last slice.`);}
function bindControl(key,callback){const el=$('#'+key);el.oninput=()=>{state[key]=Number(el.value);callback();};}
function renderExperiment(){const el=$('#experiment');switch(current.id){case 'supply-demand': el.innerHTML=`<div class="experiment-grid"><div class="controls">${control('demand','Demand shift',state.demand,-20,20,5,v=>v>0?'+'+v:v,['Lower','Higher'])}${control('supply','Supply shift',state.supply,-20,20,5,v=>v>0?'+'+v:v,['Less','More'])}<button class="reset" id="reset-market">Reset market ↺</button></div><div class="chart" id="market-chart"></div></div><div class="legend"><span><i></i>Demand</span><span><i class="dark"></i>Supply</span><span>● Market equilibrium</span></div><div class="result-line" id="market-result" aria-live="polite"></div><details class="model-details"><summary>See the simple maths</summary><p>Demand: Q = 100 + demand shift − 10P. Supply: Q = 20 + supply shift + 10P. At equilibrium the quantities match. “Shift” changes the number of cups wanted or supplied at every price. Prices and quantities are illustrative.</p></details>`;const updateMarket=()=>{const m=market(state.demand,state.supply);$('#market-chart').innerHTML=marketPlot();$('#market-result').innerHTML=`Buyers and sellers meet at <strong>${money(m.price)} a cup</strong> and <strong>${m.quantity} cups an hour</strong>. ${state.demand===0&&state.supply===0?'Try increasing demand, then increasing supply.':'More demand tends to push the price up; more supply tends to push it down.'}`;['demand','supply'].forEach(k=>$('#out-'+k).textContent=state[k]>0?'+'+state[k]:state[k]);};bindControl('demand',updateMarket);bindControl('supply',updateMarket);$('#reset-market').onclick=()=>{state.demand=state.supply=0;renderExperiment();};updateMarket();break;
case 'opportunity-cost': el.innerHTML=`<div class="experiment-grid"><div class="controls">${control('hours','Time for yourself',state.hours,0,6,1,v=>v+'h',['0 hours','6 hours'])}${control('rate','Possible hourly pay',state.rate,10,30,5,money,['€10','€30'])}<button class="reset" id="reset-time">Reset afternoon ↺</button></div><div><div class="metrics" id="time-metrics"></div><div id="time-blocks" class="time-blocks"></div><div class="legend"><span><i></i>Time for yourself</span><span><i class="dark"></i>Paid work</span></div></div></div><div class="result-line" id="time-result" aria-live="polite"></div><p class="demo-note">Assumes paid work is available for all six hours, at a constant rate, and is your next-best alternative. Enjoyment has value even when we don’t give it a price.</p>`;const updateTime=()=>{const m=saturday(state.hours,state.rate);$('#out-hours').textContent=state.hours+'h';$('#out-rate').textContent=money(state.rate);$('#time-metrics').innerHTML=metric(m.leisure+'h','Time for yourself')+metric(money(m.earned),'Earnings kept')+metric(money(m.forgone),'Earnings forgone');$('#time-blocks').innerHTML=Array.from({length:6},(_,i)=>`<div class="${i<state.hours?'leisure':''}">${i<state.hours?'Free':'Work'}</div>`).join('');$('#time-result').innerHTML=`${state.hours===0?'All six hours go to work. No potential earnings are given up.':`Keeping <strong>${state.hours} hour${state.hours===1?'':'s'}</strong> for yourself means giving up <strong>${money(m.forgone)}</strong> in possible earnings.`} The right choice depends on how much you value that time.`;};bindControl('hours',updateTime);bindControl('rate',updateTime);$('#reset-time').onclick=()=>{state.hours=3;state.rate=15;renderExperiment();};updateTime();break;
case 'comparative-advantage': el.innerHTML=`<div class="segmented" role="group" aria-label="Choose production arrangement"><button id="shared" class="${state.specialise?'':'active'}" aria-pressed="${!state.specialise}">Split both tasks</button><button id="specialise" class="${state.specialise?'active':''}" aria-pressed="${state.specialise}">Specialise & trade</button></div><div id="trade-view"></div><p class="demo-note">Each cook has one hour. Split tasks: each spends half an hour on each food. Specialisation: Sam makes only salads. Alex spends 50 minutes on sandwiches and 10 on salads, producing 5 sandwiches and 0.5 salads. Trade rate: 1 salad for 1.5 sandwiches, between their opportunity costs of 1 and 2 sandwiches per salad. Fractional portions keep the maths simple.</p>`;$('#shared').onclick=()=>{state.specialise=false;renderExperiment();};$('#specialise').onclick=()=>{state.specialise=true;renderExperiment();};const fmt=n=>Number(n.toFixed(2));$('#trade-view').innerHTML=`${state.specialise?`<div style="margin:20px 0">${control('tradeSalads','Salads Sam trades to Alex',state.tradeSalads,0,2,.25,v=>fmt(v)+(v===1?' salad':' salads'),['Keep all salads','Trade all salads'])}</div>`:''}<div id="trade-results"></div>`;const updateTrade=()=>{const m=state.specialise?trade(state.tradeSalads):{alex:[3,1.5],sam:[1,1]};if(state.specialise)$('#out-tradeSalads').textContent=fmt(state.tradeSalads)+(state.tradeSalads===1?' salad':' salads');$('#trade-results').innerHTML=`<table class="trade-table"><caption class="eyebrow" style="text-align:left;margin-bottom:10px">${state.specialise?'AFTER SPECIALISATION & EXCHANGE':'AFTER SPLITTING THE WORK'}</caption><thead><tr><th>Lunch available</th><th>Sandwiches</th><th>Salads</th></tr></thead><tbody><tr><th scope="row">Alex</th><td>${fmt(m.alex[0])}</td><td>${fmt(m.alex[1])}</td></tr><tr><th scope="row">Sam</th><td>${fmt(m.sam[0])}</td><td>${fmt(m.sam[1])}</td></tr><tr><th scope="row">Together</th><td class="gain">${state.specialise?5:4}</td><td>2.5</td></tr></tbody></table><div class="result-line" aria-live="polite">${state.specialise?(state.tradeSalads===1?'<strong>Both gain.</strong> Both keep their original salads. Alex has 3.5 sandwiches instead of 3; Sam has 1.5 instead of 1.':`Exchange changes who gets what. At <strong>1 salad traded</strong>, both have at least as much of each food as before. A larger combined output alone does not guarantee that both prefer their final lunch.`):'Together: <strong>4 sandwiches and 2.5 salads</strong>. Try specialisation to see how different opportunity costs create room for gains from trade.'}</div>`;};if(state.specialise)bindControl('tradeSalads',updateTrade);updateTrade();break;
case 'diminishing-utility':el.innerHTML=`<div class="experiment-grid"><div class="controls"><div><label class="eyebrow" for="slices">HOW MANY SLICES?</label><div class="counter"><button id="slice-minus" aria-label="Remove one slice">−</button><b id="slice-count"></b><button id="slice-plus" aria-label="Add one slice">+</button></div><input id="slices" type="range" min="0" max="6" step="1" value="${state.slices}" style="width:100%;margin-top:15px" aria-label="Number of pizza slices"></div><div class="metrics" style="grid-template-columns:1fr 1fr" id="joy-metrics"></div></div><div class="chart" id="utility-chart"></div></div><div class="legend"><span><i class="dark"></i>Total enjoyment</span><span><i></i>Extra enjoyment per slice</span></div><div class="result-line" id="joy-result" aria-live="polite"></div><p class="demo-note">Invented joy points: 10, 8, 6, 4, 2, 1 for slices 1–6. The chart illustrates a pattern; it does not measure real happiness.</p>`;const updateJoy=()=>{const m=utility(state.slices);$('#slice-count').textContent=state.slices;$('#slices').value=state.slices;$('#slice-minus').disabled=state.slices===0;$('#slice-plus').disabled=state.slices===6;$('#joy-metrics').innerHTML=metric(m.total,'Total joy')+metric(m.marginal,'Latest slice');$('#utility-chart').innerHTML=utilityPlot();$('#joy-result').innerHTML=state.slices===0?'No slices yet. Add one to see the first jump in enjoyment.':`Slice <strong>${state.slices}</strong> adds <strong>${m.marginal} point${m.marginal===1?'':'s'}</strong>. Your total is <strong>${m.total}</strong>. ${state.slices>1?'The total rises, while the extra joy gets smaller.':'The first slice gives the biggest boost in this example.'}`;};bindControl('slices',updateJoy);$('#slice-minus').onclick=()=>{state.slices=Math.max(0,state.slices-1);updateJoy();};$('#slice-plus').onclick=()=>{state.slices=Math.min(6,state.slices+1);updateJoy();};updateJoy();break;
case 'paradox-thrift':el.innerHTML=`<div class="experiment-grid"><div class="controls">${control('saving','Intended saving rate',state.saving,10,40,5,v=>v+'%',['10%','40%'])}<button class="reset" id="reset-thrift">Reset economy ↺</button><p class="demo-note">Investment stays fixed at €100 per round. This is a simplified town, not a forecast.</p></div><div><div class="metrics" id="thrift-metrics"></div><div class="money-flow"><div class="flow-box"><b id="household-flow"></b><span>Household income</span></div><span class="flow-arrow" aria-hidden="true">⇄</span><div class="flow-box"><b id="business-flow"></b><span>Consumer spending</span></div></div><div class="saving-bars" id="saving-bars" aria-hidden="true"></div><div class="legend"><span>Bar heights compare the €500 baseline with new income</span></div></div></div><div class="result-line" id="thrift-result" aria-live="polite"></div><details class="model-details"><summary>See the simple maths & assumptions</summary><p>Income Y = consumption C + investment I. Households consume (1 − s) × Y, where s is the saving share. So Y = I ÷ s. With fixed investment of €100, actual total saving s × Y remains €100. We omit government, foreign trade, taxes and interest-rate responses. Prices are fixed and firms can adjust output. Results are new equilibria, not an instant transition.</p></details>`;const updateThrift=()=>{const m=thrift(state.saving);$('#out-saving').textContent=state.saving+'%';$('#thrift-metrics').innerHTML=metric(money(m.income),'Total income')+metric(state.saving+'%','Saving share')+metric(money(m.saving),'Total saving');$('#household-flow').textContent=money(m.income);$('#business-flow').textContent=money(m.spending);$('#saving-bars').innerHTML=`<div style="height:50%"><span>Baseline €500</span></div><div style="height:${m.income/1000*100}%"><span>Now ${money(m.income)}</span></div>`;$('#thrift-result').innerHTML=`At a <strong>${state.saving}%</strong> saving rate, income settles at <strong>${money(m.income)}</strong>. Total saving stays at <strong>€100</strong> because investment is fixed. ${state.saving>20?'Households aim to save a larger share, but their income shrinks.':state.saving<20?'A smaller saving share supports more spending and a higher income in this model.':'Try raising the saving rate. Watch income adjust.'}`;};bindControl('saving',updateThrift);$('#reset-thrift').onclick=()=>{state.saving=20;renderExperiment();};updateThrift();break;
case 'prisoners-dilemma':el.innerHTML=`<div class="select-row"><label>Café A chooses<select id="choice-a"><option value="normal">Normal price</option><option value="discount">Discount</option></select></label><label>Café B chooses<select id="choice-b"><option value="normal">Normal price</option><option value="discount">Discount</option></select></label></div><div class="matrix-wrap"><table class="matrix"><caption class="eyebrow" style="text-align:left;margin-bottom:12px">PROFIT POINTS (A, B) · ILLUSTRATIVE</caption><thead><tr><th scope="col">A ↓ / B →</th><th scope="col">Normal price</th><th scope="col">Discount</th></tr></thead><tbody>${['normal','discount'].map(a=>`<tr><th scope="row">${a==='normal'?'Normal price':'Discount'}</th>${['normal','discount'].map(b=>`<td data-cell="${a},${b}"><b>${game(a,b).join(' , ')}</b><small>${a==='normal'&&b==='normal'?'Higher shared payoff':a==='discount'&&b==='discount'?'Nash equilibrium':'One café gains more'}</small></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="result-line" id="game-result" aria-live="polite"></div><p class="demo-note">A Nash equilibrium is a set of choices where neither player can improve their own payoff by changing alone. Here, discounting is also a strictly dominant strategy: it pays more against either choice by the other café.</p>`;$('#choice-a').value=state.a;$('#choice-b').value=state.b;const updateGame=()=>{const [a,b]=game(state.a,state.b);$$('[data-cell]').forEach(td=>td.classList.toggle('selected',td.dataset.cell===state.a+','+state.b));$('#game-result').innerHTML=`Café A: <strong>${a}</strong> points. Café B: <strong>${b}</strong> points. Together: <strong>${a+b}</strong>. ${state.a==='discount'&&state.b==='discount'?'Neither can improve by switching alone. Both keeping normal prices would give 30 each, but each would have a reason to discount.':state.a==='normal'&&state.b==='normal'?'Both get 30, but either can switch alone to a discount and earn 40. This outcome is better for both than mutual discounting, but it is unstable in the one-round game.':'The café charging a normal price can improve its own payoff by also discounting—from 10 to 20.'}`;};['a','b'].forEach(k=>$('#choice-'+k).onchange=e=>{state[k]=e.target.value;updateGame();});$$('[data-cell]').forEach(td=>td.onclick=()=>{[state.a,state.b]=td.dataset.cell.split(',');$('#choice-a').value=state.a;$('#choice-b').value=state.b;updateGame();});updateGame();break;
}}
function navigate(){const hash=location.hash; if(hash.startsWith('#lesson/')){const id=decodeURIComponent(hash.slice(8)),l=lessons.find(l=>l.id===id);if(l){current=l;renderLesson();requestAnimationFrame(()=>$('#workbench').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));}}}
renderCatalog();renderLesson();window.addEventListener('hashchange',navigate);if(location.hash.startsWith('#lesson/'))navigate();
